(async () => {
  const parentName = "Decking";
  const folderName = "Hacking Threads"; // change to "Hacking Threads" as needed

  const parent = game.folders?.find(f => f.type==="Item" && f.name===parentName && !f.folder);
  const folder = game.folders?.find(f => f.type==="Item" && f.name===folderName && f.folder?.id===parent?.id);

  if (!folder) {
    ui.notifications?.warn?.(`Folder not found: ${parentName} > ${folderName}`);
    return;
  }

  const items = game.items.filter(i => i.folder?.id === folder.id);
  if (!items.length) {
    ui.notifications?.info?.(`No items in ${folderName}.`);
    return;
  }

  await Item.deleteDocuments(items.map(i => i.id));
  ui.notifications?.info?.(`Deleted ${items.length} items from ${folderName}.`);
})();
